file_editor: {"command": "create", "path": "/root/output/css/style.css", "file_text": ":root {
  --bg: #0b1020;
  --panel: #0f1833;
  --panel-2: #0c1430;
  --text: #e7ecff;
  --muted: rgba(231, 236, 255, 0.7);
  --grid: rgba(231, 236, 255, 0.12);
  --accent: #7aa6ff;
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
}

body {
  margin: 0;
  font-family: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  background: radial-gradient(1200px 700px at 20% 10%, rgba(122, 166, 255, 0.18), transparent 55%),
              radial-gradient(900px 600px at 85% 10%, rgba(120, 255, 220, 0.10), transparent 50%),
              var(--bg);
  color: var(--text);
}

header {
  padding: 18px 20px 8px;
}

header h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 650;
  letter-spacing: 0.2px;
}

header .subtitle {
  margin: 6px 0 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.3;
}

.layout {
  display: flex;
  gap: 14px;
  padding: 12px 14px 18px;
  align-items: stretch;
}

.panel {
  background: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.02));
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.35);
  overflow: hidden;
  min-height: 640px;
}

.panel-left {
  flex: 1 1 58%;
  min-width: 720px;
}

.panel-right {
  flex: 1 1 42%;
  min-width: 520px;
}

.panel-header {
  padding: 12px 14px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.panel-header h2 {
  margin: 0;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: 0.2px;
}

#legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  align-items: center;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
}

.legend-swatch {
  width: 10px;
  height: 10px;
  border-radius: 3px;
  border: 1px solid rgba(255,255,255,0.25);
}

#bubble-container {
  padding: 12px;
}

#bubble-svg {
  width: 100%;
  height: auto;
  display: block;
  background: linear-gradient(180deg, rgba(0,0,0,0.15), rgba(0,0,0,0.04));
  border-radius: 10px;
}

.node circle {
  stroke: rgba(255,255,255,0.35);
  stroke-width: 1px;
}

.node text {
  font-size: 11px;
  fill: rgba(255,255,255,0.92);
  font-weight: 700;
  letter-spacing: 0.2px;
  paint-order: stroke;
  stroke: rgba(0,0,0,0.35);
  stroke-width: 2px;
  stroke-linejoin: round;
  user-select: none;
  pointer-events: none;
}

.node.selected circle {
  stroke: #ffffff;
  stroke-width: 2px;
  filter: drop-shadow(0 6px 10px rgba(0,0,0,0.5));
}

.tooltip {
  position: absolute;
  pointer-events: none;
  padding: 10px 12px;
  background: rgba(15, 24, 51, 0.96);
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 10px;
  box-shadow: 0 10px 26px rgba(0,0,0,0.45);
  color: var(--text);
  font-size: 12px;
  line-height: 1.25;
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 120ms ease, transform 120ms ease;
  z-index: 50;
  max-width: 380px;
}

.tooltip.visible {
  opacity: 1;
  transform: translateY(0);
}

.tooltip .ticker {
  font-weight: 800;
  letter-spacing: 0.2px;
}

.tooltip .muted {
  color: var(--muted);
}

#table-container {
  padding: 12px;
}

.table-scroller {
  max-height: 560px;
  overflow: auto;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  background: rgba(0,0,0,0.12);
}

.stock-table {
  width: 100%;
  border-collapse: collapse;
}

.stock-table thead th {
  position: sticky;
  top: 0;
  background: rgba(11, 16, 32, 0.96);
  backdrop-filter: blur(8px);
  text-align: left;
  font-size: 12px;
  color: var(--muted);
  padding: 10px 10px;
  border-bottom: 1px solid rgba(255,255,255,0.10);
  white-space: nowrap;
}

.stock-table tbody td {
  padding: 9px 10px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  font-size: 13px;
  vertical-align: middle;
}

.stock-table tbody tr {
  cursor: pointer;
}

.stock-table tbody tr:hover {
  background: rgba(122, 166, 255, 0.10);
}

.stock-table tbody tr.selected {
  background: rgba(122, 166, 255, 0.18);
  outline: 1px solid rgba(255,255,255,0.15);
}

.stock-table td.marketcap {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.stock-table td.ticker {
  font-weight: 800;
  letter-spacing: 0.2px;
}

.footer-note {
  padding: 10px 14px 14px;
  color: var(--muted);
  font-size: 12px;
}

@media (max-width: 1260px) {
  .layout {
    flex-direction: column;
  }

  .panel-left, .panel-right {
    min-width: unset;
  }

  .panel {
    min-height: unset;
  }

  .table-scroller {
    max-height: 420px;
  }
}
